/**
 * Gets a number from local storage and parses it to be a number.
 * If the number does not exists, or cannot be parsed, then undefined is returned.
 * @param localStorageKey
 * @returns
 */
export function getNumberFromLocalStorage(localStorageKey) {
    const item = localStorage.getItem(localStorageKey);
    if (item == null) {
        return;
    }
    const itemAsNumber = Number(item);
    if (!isNaN(itemAsNumber)) {
        return itemAsNumber;
    }
}
